"""Regenerate the terrain fixtures' heights (W1a; stdlib only, deterministic).

  Content/terrain/hills.swterrain, hills.r16  257 points a side, 2 m apart (512 m): rolling
                                              hills from a few sine waves, 0..60 m
  Content/terrain/layers.swterrain, .r16,     W1b: 65 points, 2 m apart (128 m), flat, painted
  layers.weights.png                          with four layers, one per quadrant, all four
                                              mixed in a disc at the centre
Run it after changing it; the outputs are committed so tests don't need Python. The scenes
that place it (Scenes/terrain-*.swscene) are written by hand.
"""
import math, struct, zlib
from pathlib import Path

root = Path(__file__).resolve().parents[1]


def hills(samples=257, spacing=2.0, low=0.0, high=60.0):
    values = []
    for z in range(samples):
        for x in range(samples):
            px, pz = x * spacing, z * spacing
            h = (24 + 12 * math.sin(px / 40.0) * math.cos(pz / 55.0) + 6 * math.sin(px / 17.0 + pz / 23.0) +
                 3 * math.cos(px / 7.0 - pz / 11.0))
            values.append(max(0, min(65535, round((h - low) / (high - low) * 65535))))
    return struct.pack('<%dH' % len(values), *values)


terrain = root / 'Content/terrain'
terrain.mkdir(parents=True, exist_ok=True)
(terrain / 'hills.r16').write_bytes(hills())
(terrain / 'hills.swterrain').write_text(
    '# Generated by Tests/fixtures/graphics/Tools/terrain.py; edit that, not this file.\n'
    'swterrain 1\nsamples 257\nspacing 2\nheight_range 0 60\nheights "terrain/hills.r16"\nuv_metres 4\n')


def png_rgba(width, height, rgba):
    def chunk(kind, data):
        body = kind + data
        return struct.pack('>I', len(data)) + body + struct.pack('>I', zlib.crc32(body) & 0xffffffff)
    rows = b''.join(b'\0' + bytes(rgba[y * width * 4:(y + 1) * width * 4]) for y in range(height))
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 6, 0, 0, 0)) +
            chunk(b'IDAT', zlib.compress(rows, 9)) + chunk(b'IEND', b''))


def layer_weights(samples=65, mix_radius=6):
    # Rows from the lowest Z. Quadrants: layer 0 at low X and Z, 1 at high X, 2 at high Z,
    # 3 at both; within mix_radius points of the centre all four share alike.
    half = samples // 2
    out = []
    for z in range(samples):
        for x in range(samples):
            w = [0, 0, 0, 0]
            if math.hypot(x - half, z - half) <= mix_radius:
                w = [64, 64, 64, 63]
            else:
                w[(1 if x > half else 0) + (2 if z > half else 0)] = 255
            out += w
    return out


(terrain / 'layers.r16').write_bytes(struct.pack('<%dH' % (65 * 65), *([0] * (65 * 65))))
(terrain / 'layers.weights.png').write_bytes(png_rgba(65, 65, layer_weights()))
(terrain / 'layers.swterrain').write_text(
    '# Generated by Tests/fixtures/graphics/Tools/terrain.py; edit that, not this file.\n'
    'swterrain 2\nsamples 65\nspacing 2\nheight_range 0 10\nheights "terrain/layers.r16"\n'
    'layer 0 "materials/terrain/red.swmaterial" 4\n'
    'layer 1 "materials/terrain/green.swmaterial" 4\n'
    'layer 2 "materials/terrain/blue.swmaterial" 4\n'
    'layer 3 "materials/terrain/yellow.swmaterial" 4\n'
    'weights "terrain/layers.weights.png"\n')
